<?php
declare(strict_types=1);
require __DIR__.'/config/bootstrap.php';
$q=trim((string)($_GET['q']??''));$posts=[];
if($q!==''){$s=$pdo->prepare("SELECT p.*,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='published' AND (p.title LIKE ? OR p.excerpt LIKE ? OR p.content LIKE ?) ORDER BY p.published_at DESC LIMIT 50");$like='%'.$q.'%';$s->execute([$like,$like,$like]);$posts=$s->fetchAll();}
$pageTitle='Search articles · Paper Cast';require __DIR__.'/includes/header.php'; ?>
<section class="section-heading"><div><span class="eyebrow">SEARCH THE JOURNAL</span><h2>Find a story</h2></div></section><form class="site-search" action="search.php" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search articles, topics, and ideas…" autofocus><button type="submit">Search</button></form><?php if($q!==''): ?><p class="muted"><?= count($posts) ?> result(s) for “<?= e($q) ?>”</p><section class="article-grid"><?php foreach($posts as $post): ?><article class="article-card"><?php if($post['cover_image']): ?><a class="article-image" href="<?= e(site_url('article.php?slug='.rawurlencode($post['slug']))) ?>"><img src="<?= e($post['cover_image']) ?>" alt=""></a><?php endif ?><div class="meta"><?= e($post['category_name']??'Journal') ?></div><h3><a href="<?= e(site_url('article.php?slug='.rawurlencode($post['slug']))) ?>"><?= e($post['title']) ?></a></h3><p><?= e($post['excerpt']?:excerpt($post['content'])) ?></p></article><?php endforeach ?></section><?php if(!$posts): ?><p>No articles matched your search. Try another phrase.</p><?php endif ?><?php endif ?><?php require __DIR__.'/includes/footer.php'; ?>
